const checks = { unit: "npm test", lint: "npm run lint", types: "npx tsc --noEmit" };
const results = await Promise.all(Object.values(checks).map((command) => tool("Bash", { command }).then(() => "ok", (error) => error.message.slice(0, 2000))));
return Object.fromEntries(Object.keys(checks).map((name, index) => [name, results[index]]));

const files = (await $`rg -l fetchUser src test`).trim().split("\n");
for (const file of files) await $`sed -i '' s/fetchUser/loadUser/g ${file}`;
return { files, tests: await $`npm test`.nothrow() };

const crates = (await $`fd Cargo.toml crates --max-depth 2`).trim().split("\n").map((manifest) => manifest.replace("/Cargo.toml", ""));
const counts = await Promise.all(crates.map((crate) => $`rg -c TODO ${crate} --no-filename`.nothrow()));
return crates.map((crate, index) => [crate, counts[index].split("\n").filter(Boolean).reduce((sum, n) => sum + Number(n), 0)]);

const packages = JSON.parse(await $`cat package.json`).workspaces;
for (const pkg of packages) await $`npm --prefix ${pkg} run build`;
return packages;

